"""Method figures and replay widgets built from recorded COMPASS artifacts."""
from html import escape as e
import json

DOC='https://docs.google.com/document/d/1H76U3hDNDe5E_JY4HZYSGUGbulYV-CGbZnrcT1s-fow/edit'

def pipeline():
    stages=[('01','Task context','Instruction or demonstration','Objects, rules, and the intended outcome.'),('02','System 2 → SceneCode','Program construction','Write the scene, subgoals, commands, and checks.'),('03','Ground the objects','SAM3 + RGB-D','Resolve image anchors into masks and metric targets.'),('04','Encode the target','Learned bridge','Combine target geometry, robot state, and visual features.'),('05','Execute with pi0.5','Frozen System 1','Inject the bridge vector and produce an action chunk.'),('06','Observe and revise','Execution feedback','Compare the new scene with expect and update the program.')]
    return '<figure class="pipeline-figure wide"><div class="pipeline-grid">'+''.join(f'<div class="pipeline-stage"><span class="pipeline-index">{n}</span><span class="mini-label">{e(sub)}</span><h3>{e(title)}</h3><p>{e(body)}</p></div>' for n,title,sub,body in stages)+'</div><div class="pipeline-feedback">New observations → System 2 → updated SceneCode → next action</div><figcaption>The program is carried through the full task loop, from context to checked execution.</figcaption></figure>'

def encoder():
    return '''<figure class="encoder-figure wide"><div class="encoder-top"><div class="encoder-input"><span class="mini-label">GROUNDED EXECUTION FEATURES</span><h3>Target + robot state</h3><p>Target point and hand-to-target offset<br>Hand / joint state · active arm · execution phase</p><div class="encoder-visual"><span class="mini-label">CURRENT OBSERVATION</span><p>Pooled pi0.5 visual features → learned projection</p></div></div><span class="encoder-arrow">→</span><div class="encoder-network"><span class="mini-label">TRAINABLE · ≈3.8M PARAMETERS</span><div class="network-layers"><div>768<span>tanh</span></div><span>→</span><div>768<span>tanh</span></div><span>→</span><div>2048<span>bridge vector</span></div></div><p>Visual and geometric features meet in the first hidden layer.</p></div></div><div class="encoder-injection"><div><span class="mini-label">FROZEN PI0.5 · PALIGEMMA</span><h3>Inject into the language-token residual</h3><p class="encoder-equation">h<sub>10</sub> ← h<sub>10</sub> + α · e<sub>ϕ</sub>(f, v)</p><p>The action expert then generates the robot’s action chunk.</p></div><span class="layer-badge">Layer <b>10</b></span></div><figcaption>Default MLP interface: two 768-unit hidden layers and a 2,048-dimensional output. The policy weights stay frozen.</figcaption></figure>'''

def fields():
    rows=[('Objects & state','What is present, where it is, and what is currently held.','orange_block · anchor [325, 254] · held by left gripper'),('Relations','How objects and the robot relate to each other.','above(yellow_block, orange_block)'),('Commands','What should happen during the next action segment.','steer → orange_block · object = yellow_block · release = true'),('Expected outcomes','What the next observation should establish.','on_top(yellow_block, orange_block)')]
    return '<div class="scenecode-fields wide">'+''.join(f'<div><span class="mini-label">{e(name)}</span><p>{e(desc)}</p><code>{e(ex)}</code></div>' for name,desc,ex in rows)+'</div>'

def study(case,traces,title,description):
    t=traces[case['id']];u=t['updates'][0];task=case['id'];buttons=''.join(f'<button type="button" data-replay-index="{i}" aria-pressed="{str(i==0).lower()}"><b>{s["time"]:.2f}s</b><span>step {s["step"]}</span></button>' for i,s in enumerate(t['updates']))
    tabs=''.join(f'<button type="button" role="tab" data-code-view="{key}" aria-selected="{str(i==0).lower()}" aria-controls="code-{task}">{label}</button>' for i,(key,label) in enumerate([('scene','SceneCode'),('commands','Commands'),('expect','Checks'),('facts','3D targets')]))
    return f'''<section class="case-study wide" id="study-{task}" data-sync-case="{task}"><header class="study-heading"><span class="mini-label">CASE STUDY / {e(case['category'])}</span><h3>{e(title)}</h3><p>{e(description)}</p></header><div class="sync-grid"><div class="sync-film"><div class="sync-stage"><video class="case-video sync-video" controls muted playsinline preload="none" poster="{case['poster']}" aria-label="{e(title,quote=True)}"><source data-src="{case['video']}" type="video/mp4"></video><svg class="scene-anchors" viewBox="0 0 640 360" aria-label="Object image anchors"></svg></div><div class="sync-options"><label><input type="checkbox" data-show-anchors checked> Object anchors</label><a href="{DOC}" target="_blank" rel="noopener" class="review-link" data-review-moment>Comment at this moment ↗</a></div><p class="sync-progress">{e(u['progress'])}</p><div class="replay-timeline" aria-label="Recorded SceneCode review points">{buttons}</div><div class="sync-download"><a href="/blog/assets/compass/{task}-scenecode.mp4" target="_blank" rel="noopener">Open synchronized video ↗</a><a href="/blog/assets/compass/scenecode-traces.json" download>Recorded snapshots ↓</a></div></div><div class="sync-codebox"><div class="sync-code-head"><span>SCENECODE / RECORDED UPDATE</span><b data-code-time>00:00.00</b></div><div class="code-tabs" role="tablist" aria-label="SceneCode view">{tabs}</div><pre id="code-{task}" class="sync-code" role="tabpanel" tabindex="0"><code>{e(u['scene_code'])}</code></pre><div class="sync-code-foot"><span data-code-step>Control step 0</span><span>Changes at recorded review points</span></div></div></div></section>'''

def components(root):
    assets=root/'blog/assets/compass';cases={c['id']:c for c in json.loads((assets/'cases.json').read_text())};traces=json.loads((assets/'scenecode-traces.json').read_text())
    return {'<!-- PIPELINE -->':pipeline(),'<!-- ENCODER -->':encoder(),'<!-- SCENECODE_FIELDS -->':fields(),
    '<!-- STUDY_STACK -->':study(cases['stack_blocks_by_language'],traces,'Keep the intended order while the scene changes.','The task fixes the final color order. The recorded reviews change the immediate subgoal: first approach the yellow block, then place the grasped orange block as the base, and then guide the yellow block onto it.'),
    '<!-- STUDY_MEMORY -->':study(cases['cover_blocks'],traces,'Remember a color order after the objects disappear.','Three cups cover the colored blocks. SceneCode retains the required red → green → blue uncovering order while updating which cups and blocks are currently visible.'),
    '<!-- STUDY_DESK -->':study(cases['organize_table'],traces,'Carry one plan across several objects and destinations.','The mouse, keyboard, figurine, clock, and leftover objects have different destinations. The program tracks completed placements and selects what remains to be done.')}
